INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'el-enigma-de-las-sombras-secretas', 'El Enigma de las Sombras Secretas', 'Dinámica de observación espejo y parejas secretas donde los scouts imitan las posturas de un compañero asignado al azar para descubrir a su sombra.', '<h2>📜 Descripción de El Enigma de las Sombras Secretas</h2>
<p><b>El Enigma de las Sombras Secretas</b> es una dinámica scout de observación en espejo, deducción visual y atención de grupo. La actividad se juega dividiendo a la unidad en dos equipos de igual tamaño: los <b>Líderes de Pose</b> y las <b>Sombras Secretas</b>. Antes de comenzar a moverse, cada Sombra saca en secreto una tarjeta con el nombre de un Líder a quien deberá imitar durante todo el juego, manteniendo en estricto secreto la identidad de su pareja.</p>
<p>Al detenerse la música, los Líderes congelan una postura corporal y las Sombras deben ubicarse rápidamente a sus espaldas imitando el gesto exacto. La diversión radica en que los Líderes deben observar las figuras del entorno para descubrir cuál de todos los participantes está actuando como su Sombra personal.</p>

<h2>🎲 ¿Cómo se juega El Enigma de las Sombras Secretas?</h2>
<p>Para llevar a cabo la dinámica con máxima claridad y entretención, los dirigentes deben seguir estos cuatro pasos sencillos:</p>
<ul>
  <li><b>Paso 1 - Sorteo Secreto:</b> Cada jugador del equipo de las <i>Sombras</i> saca de una bolsa un papel con el nombre de un jugador del equipo de los <i>Líderes</i>. El equipo de los Líderes NO sabe quién es la Sombra de quién.</li>
  <li><b>Paso 2 - Desplazamiento y Pausa:</b> Todos los participantes caminan o trotan dispersos por la sala al ritmo de la música o aplausos del dirigente. Al detenerse el sonido, cada Líder se congela al instante haciendo una pose libre de estatua (ej. postura de animal, héroe o técnica scout).</li>
  <li><b>Paso 3 - La Imitación en Espejo:</b> En ese mismo segundo, cada Sombra busca con la vista a su Líder asignado en secreto, se coloca detrás o al lado de él y copia exactamente su misma postura corporal.</li>
  <li><b>Paso 4 - El Descubrimiento:</b> Cada Líder gira la mirada, observa las posturas réplica de su alrededor e intenta adivinar cuál participante es su Sombra Secreta. Si lo descubre correctamente, la pareja se abraza y suma 1 punto para su equipo.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de El Enigma de las Sombras Secretas</h2>
<p>El sistema de puntuación premia la rapidez de imitación y el ojo observador en el Tally:</p>
<ul>
  <li><b>Punto por Acierto Directo:</b> Otorgar 3 puntos a cada Líder que identifique a su Sombra Secreta en el primer intento.</li>
  <li><b>Imitación Más Fiel:</b> Otorgar 5 puntos a la Sombra que logre la réplica postural más idéntica y precisa.</li>
  <li><b>Espíritu de Integración:</b> Otorgar 3 puntos a la patrulla o seisena que complete todas sus parejas en el menor tiempo.</li>
</ul>', '/uploads/el-enigma-de-las-sombras-secretas.webp', 'publicado', '{"areas": ["sociabilidad", "creatividad", "afectividad"], "unidades": ["manada", "compañía", "tropa"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Tarjetas de Nombres"], "objetivos": ["Estimular la atención a los detalles", "Fomentar la comunicación e interpretación", "Conocer a los demás", "Fomentar un entorno de confianza"], "justificacion_areas": "El Enigma de las Sombras Secretas potencia la sociabilidad al ejercitar el conocimiento mutuo, la atención respetuosa hacia los pares y la desinhibición social. Desarrolla la creatividad al requerir la adaptación kinésica inmediata y la réplica dramática de figuras anatómicas. Fortalece la afectividad al construir lazos de confianza y empatía no verbal dentro de la patrulla.", "variaciones": "<b>Variante de Presentación:</b> Ideal para los primeros días de campamento; al descubrir a la Sombra, la pareja debe compartir tres datos personales antes de la siguiente ronda.<br><b>Sombras de Sonidos Scouts:</b> La Sombra no solo imita la postura sino también el sonido de animal o clave emitida por el Líder.<br><b>Sombras con Distintivos de Color:</b> Colocar brazaletes de colores a los Líderes para facilitar la identificación visual en grupos grandes.", "recomendaciones": "Fomentar un ambiente festivo y libre de presiones para que los beneficiarios disfruten la observación sin temor a fallar. Adaptar la velocidad de la música a la edad de la unidad. Verificar que todos los nombres en la bolsa estén escritos con letra clara.", "objetivos_educativos": [{"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Respetando con honestidad la asignación secreta de mi pareja de juego."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Acatando las reglas de congelación de postura sin hablar durante la prueba."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Favoreciendo el juego limpio y el respeto a la observación de cada pareja."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Promoviendo un ambiente de integración, escucha atenta y lealtad de patrulla."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Cumpliendo con lealtad las consignas de imitación secreta."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Afianzando la cohesión y hermandad comunitaria en toda la Tropa."}, {"id": "ec280dd0-2d80-4b84-86ad-2d362da14886", "area": "Creatividad", "unidad": "Manada", "texto": "Me gusta participar en juegos de observación.", "como_se_cumple": "Observando con detalle las posturas de los compañeros para replicarlas con precisión."}, {"id": "dcdcce42-6b31-45f7-a135-290f0f74b5a6", "area": "Creatividad", "unidad": "Manada", "texto": "Me gustan los juegos en que tengo que usar mi agilidad mental.", "como_se_cumple": "Deduciendo con agilidad cuál de los observadores es mi Sombra Secreta."}, {"id": "e1b7276f-4fd2-4c39-a32a-bd7fadbee702", "area": "Creatividad", "unidad": "Compañía", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Expresando reflexiones sobre la experiencia de imitar e interpretar al otro."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "unidad": "Compañía", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Analizando la perspectiva corporal de la Sombra desde el ángulo del Modelo."}, {"id": "49ae6ac6-be8f-4f2c-8b3e-6711d041181f", "area": "Creatividad", "unidad": "Tropa", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Aportando dinamismo e improvisación postural en cada ronda de juego."}, {"id": "3d0dff9b-11cd-4a30-b3a6-ec011ad95062", "area": "Creatividad", "unidad": "Tropa", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Sintetizando señas físicas sutiles para identificar a la pareja de imitación."}, {"id": "ab6e594f-b0a0-4e6d-96aa-7779299b02ef", "area": "Afectividad", "unidad": "Manada", "texto": "Trato con cariño a los demás en la Manada y me gusta que me traten igual.", "como_se_cumple": "Tratando con empatía y atención a mi pareja al sincronizar los movimientos."}, {"id": "c8993915-0234-464c-934e-2a09f8c4338e", "area": "Afectividad", "unidad": "Manada", "texto": "Digo lo que pienso sin ofender o insultar a mis compañeros ni burlarme de ellos.", "como_se_cumple": "Disfrutando de la imitación sin burlas y celebrando los aciertos del grupo."}, {"id": "2f8359db-221e-4a64-b2df-2b3e7b74a2db", "area": "Afectividad", "unidad": "Compañía", "texto": "Escucho las opiniones de las demás personas y si no estoy de acuerdo lo digo con respeto.", "como_se_cumple": "Escuchando con atención visual al compañero para sintonizar con su estado de ánimo."}, {"id": "672a5da0-8cab-42bb-85dd-0d1f285a1b91", "area": "Afectividad", "unidad": "Compañía", "texto": "Digo lo que pienso con respeto hacia las demás personas.", "como_se_cumple": "Comunicando impresiones con asertividad y construyendo un entorno de confianza."}, {"id": "a4060c60-7ce9-425b-bf2a-76941a689937", "area": "Afectividad", "unidad": "Tropa", "texto": "Escucho las opiniones de los demás personas y si no estoy de acuerdo lo digo con respeto.", "como_se_cumple": "Desarrollando empatía no verbal para comprender las intenciones posturales de la patrulla."}, {"id": "4ade9c82-6b0d-4a44-8bc6-2eb47a011ffb", "area": "Afectividad", "unidad": "Tropa", "texto": "Digo lo que pienso con respeto hacia los demás personas.", "como_se_cumple": "Demostrando lealtad y apoyo afectivo sincero hacia cada integrante del grupo."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

